1	import { describe, expect, it } from "vitest";
2	import {
3	  canAct,
4	  createDuelState,
5	  defaultDuelConfig as config,
6	  duelInput as I,
7	  MOVESET_VERSION,
8	  mirrorBox,
9	  overlaps,
10	  stepDuel,
11	  traceDuel,
12	  worldBox,
13	  type DuelInputs,
14	  type DuelState,
15	  type FighterState,
16	} from "./index.js";
17	
18	const { rules, fighter: body, arena } = config.moveset;
19	const HALF = body.pushbox.halfWidth;
20	const RIGHT_WALL = arena.width - HALF;
21	const R = I("right");
22	const L = I("left");
23	const LIGHT = I("light");
24	const HEAVY = I("heavy");
25	const THROW = I("light", "heavy");
26	
27	/** A duel with the fighters at `x0` and `x1`, optionally changed, at `frame`. */
28	function duel(x0: number, x1: number, patch0: Partial<FighterState> = {}, patch1: Partial<FighterState> = {}, frame = 0): DuelState {
29	  const state = createDuelState(config, { x: [x0, x1] });
30	  return { ...state, frame, fighters: [{ ...state.fighters[0], ...patch0 }, { ...state.fighters[1], ...patch1 }] };
31	}
32	
33	/** Player two against the right wall (holding right is its guard), player one `dx` to its left. */
34	function cornered(dx: number, patch0: Partial<FighterState> = {}, patch1: Partial<FighterState> = {}): DuelState {
35	  return duel(RIGHT_WALL - dx, RIGHT_WALL, patch0, patch1);
36	}
37	
38	function hold(frames: number, p1 = 0, p2 = 0): DuelInputs[] {
39	  return Array.from({ length: frames }, () => [p1, p2] as const);
40	}
41	
42	function script(...parts: DuelInputs[][]): DuelInputs[] {
43	  return parts.flat();
44	}
45	
46	/** Every state from the initial one; `trace[k]` is the state after k frames. */
47	function run(state: DuelState, inputs: readonly DuelInputs[]): DuelState[] {
48	  return traceDuel(config, state, inputs);
49	}
50	
51	function events(trace: readonly DuelState[]) {
52	  return trace.flatMap((state) => state.events.map((event) => ({ frame: state.frame, ...event })));
53	}
54	
55	/** The first frame after `after` on which the fighter can start something. */
56	function firstFreeFrame(trace: readonly DuelState[], index: 0 | 1, after: number): number {
57	  for (let frame = after; frame < trace.length; frame++) if (canAct(trace[frame]!.fighters[index])) return frame + 1;
58	  throw new Error("the fighter never became free");
59	}
60	
61	describe("round and result (§7)", () => {
62	  it("starts both fighters apart, facing each other, with 1,000 health and full stamina", () => {
63	    const state = createDuelState(config);
64	    expect(state).toMatchObject({ frame: 0, phase: "round", result: null, movesetVersion: MOVESET_VERSION });
65	    expect(state.fighters[0]).toMatchObject({ x: arena.width / 2 - arena.startGap / 2, y: 0, facing: 1, health: 1000, stamina: 100, action: "idle" });
66	    expect(state.fighters[1]).toMatchObject({ x: arena.width / 2 + arena.startGap / 2, y: 0, facing: -1, health: 1000, stamina: 100 });
67	    // No free opening hit: nothing reaches from the start positions.
68	    const trace = run(state, script(hold(1, HEAVY, I("down", "heavy")), hold(30), hold(1, I("special1"), LIGHT), hold(60)));
69	    expect(events(trace)).toEqual([]);
70	  });
71	
72	  it("ends the one round after 3,600 frames and gives the timeout to higher health", () => {
73	    expect(rules.roundFrames).toBe(3600);
74	    const trace = run(duel(3000, 7000, { health: 640 }, { health: 700 }), hold(3600));
75	    expect(trace[3599]!.result).toBeNull();
76	    expect(trace[3600]!.result).toEqual({ winner: 1, reason: "timeout", frame: 3600 });
77	    expect(trace[3600]!.phase).toBe("over");
78	  });
79	
80	  it("goes to ten seconds of overtime on equal health, and an exact tie after it is a draw", () => {
81	    const trace = run(createDuelState(config), hold(4200));
82	    expect(trace[3600]).toMatchObject({ phase: "overtime", result: null });
83	    expect(trace[4199]!.result).toBeNull();
84	    expect(trace[4200]!.result).toEqual({ winner: null, reason: "overtime", frame: 4200 });
85	  });
86	
87	  it("compares health again when overtime ends", () => {
88	    const tied = run(createDuelState(config), hold(3600))[3600]!;
89	    const close: DuelState = { ...tied, fighters: [{ ...tied.fighters[0], x: 5000 }, { ...tied.fighters[1], x: 5600 }] };
90	    const trace = run(close, script(hold(1, LIGHT), hold(599)));
91	    expect(trace[600]!.fighters[1].health).toBe(955);
92	    expect(trace[600]!.result).toEqual({ winner: 0, reason: "overtime", frame: 4200 });
93	  });
94	
95	  it("only advances the frame counter once the duel is over", () => {
96	    const over = run(createDuelState(config), hold(4200))[4200]!;
97	    const after = stepDuel(config, over, [R, LIGHT]);
98	    expect(after).toEqual({ ...over, frame: 4201, events: [] });
99	  });
100	
101	  it("lets a KO on the final round frame beat the timeout", () => {
102	    // Player two leads on health, so the timeout would be theirs; player one's jab lands on frame 3600.
103	    const start = duel(5000, 5600, { health: 40 }, { health: 45 }, 3592);
104	    expect(run(start, hold(8))[8]!.result).toEqual({ winner: 1, reason: "timeout", frame: 3600 });
105	    const trace = run(start, script(hold(1, LIGHT), hold(7)));
106	    expect(trace[8]!.frame).toBe(3600);
107	    expect(trace[8]!.result).toEqual({ winner: 0, reason: "ko", frame: 3600 });
108	  });
109	
110	  it("makes two simultaneous lethal hits a draw", () => {
111	    const trace = run(duel(5000, 5600, { health: 45 }, { health: 45 }), script(hold(1, LIGHT, LIGHT), hold(7)));
112	    expect(trace[8]!.fighters.map((fighter) => fighter.health)).toEqual([0, 0]);
113	    expect(trace[8]!.result).toEqual({ winner: null, reason: "double-ko", frame: 8 });
114	  });
115	
116	  it("applies both fighters' hits of a frame before declaring a KO, whichever player is first", () => {
117	    for (const lethal of [0, 1] as const) {
118	      const start = duel(5000, 5600, lethal === 0 ? {} : { health: 45 }, lethal === 0 ? { health: 45 } : {});
119	      const trace = run(start, script(hold(1, LIGHT, LIGHT), hold(7)));
120	      const frame = trace[8]!;
121	      expect(frame.fighters[lethal].health).toBe(955);
122	      expect(frame.fighters[lethal === 0 ? 1 : 0].health).toBe(0);
123	      expect(frame.result).toEqual({ winner: lethal, reason: "ko", frame: 8 });
124	    }
125	  });
126	});
