128	describe("movement (§7, §8)", () => {
129	  it("walks forward and back at their speeds", () => {
130	    const trace = run(duel(3000, 7000), script(hold(10, R, L), hold(10, L, R)));
131	    expect(trace[10]!.fighters.map((fighter) => fighter.x)).toEqual([3000 + 10 * body.walkForwardSpeed, 7000 - 10 * body.walkForwardSpeed]);
