158	  it("auto-faces the opponent after a jump crosses over them", () => {
159	    const trace = run(duel(4000, 4992), script(hold(1, I("up", "right")), hold(50)));
160	    const [one, two] = trace[51]!.fighters;
161	    expect(one.x).toBeGreaterThan(two.x);
162	    expect([one.facing, two.facing]).toEqual([-1, 1]);
163	  });
