165	  it("dashes forward and backdashes for 20 stamina each, and not below 20", () => {
166	    const dash = run(duel(3000, 7000), script(hold(1, I("dash")), hold(20)));
167	    expect(dash[1]!.fighters[0]).toMatchObject({ action: "dash", stamina: 80 });
168	    expect(dash[21]!.fighters[0]).toMatchObject({ x: 3000 + body.dashFrames * body.dashSpeed, action: "idle" });
169	    const backdash = run(duel(3000, 7000), script(hold(1, I("left", "dash")), hold(20)));
170	    expect(backdash[1]!.fighters[0]).toMatchObject({ action: "backdash", stamina: 80 });
171	    expect(backdash[21]!.fighters[0].x).toBe(3000 - body.backdashFrames * body.backdashSpeed);
172	    const tired = run(duel(3000, 7000, { stamina: 19 }), script(hold(1, I("dash")), hold(20)));
173	    expect(tired[21]!.fighters[0]).toMatchObject({ x: 3000, stamina: 19 });
174	  });
175	
176	  it("keeps fighters inside the walls", () => {
177	    const trace = run(duel(HALF + 100, RIGHT_WALL - 100), script(hold(10, L, R), hold(1, I("left", "dash"), I("right", "dash")), hold(20)));
178	    for (const state of trace.slice(10)) expect(state.fighters.map((fighter) => fighter.x)).toEqual([HALF, RIGHT_WALL]);
179	  });
180	
181	  it("never lets the two pushboxes overlap", () => {
182	    const trace = run(duel(5000, 5600), script(hold(40, R), hold(20, I("dash"), I("dash"))));
183	    for (const state of trace) expect(Math.abs(state.fighters[1].x - state.fighters[0].x)).toBeGreaterThanOrEqual(2 * HALF);
184	    expect(trace[40]!.fighters[1].x).toBeGreaterThan(5600);
