188	describe("guard (§7)", () => {
189	  const outcome = (p1: number, p2: number, frames = 30) =>
190	    events(run(cornered(600), script(hold(1, p1, p2), hold(frames, 0, p2)))).map(({ kind, moveId }) => `${kind} ${moveId}`);
191	
192	  it("blocks highs and mids with standing guard (holding back)", () => {
193	    expect(outcome(HEAVY, R)).toEqual(["block heavy-mid"]);
