224	describe("throws (§7)", () => {
225	  it("beats standing and crouching guard, landing after the ten-frame escape window", () => {
226	    for (const guard of [R, I("down", "right")]) {
227	      const trace = run(cornered(600), script(hold(1, THROW, guard), hold(40, 0, guard)));
228	      expect(events(trace)).toEqual([
229	        { frame: 13, kind: "grab", attacker: 0, moveId: "throw", damage: 0 },
230	        { frame: 24, kind: "throw", attacker: 0, moveId: "throw", damage: 120 },
231	      ]);
232	      expect(trace[24]!.fighters[1]).toMatchObject({ health: 880, action: "knockdown" });
233	    }
234	  });
235	
236	  it("can be escaped by either player on any of the ten frames after the grab", () => {
237	    // Player one throws player two into the right wall, or player two throws player one into the left wall.
238	    const setups = [
239	      { thrower: 0, start: cornered(600) },
240	      { thrower: 1, start: duel(HALF, HALF + 600) },
241	    ] as const;
242	    for (const { thrower, start } of setups) {
243	      const defender = thrower === 0 ? 1 : 0;
244	      const attempt = (frame: number) => {
245	        const inputs = hold(40);
246	        inputs[0] = thrower === 0 ? [THROW, 0] : [0, THROW];
247	        inputs[frame - 1] = defender === 0 ? [THROW, 0] : [0, THROW];
248	        const trace = run(start, inputs);
249	        return { trace, kinds: events(trace).map((event) => `${event.frame} ${event.kind}`) };
250	      };
251	      for (const frame of [14, 23]) {
252	        const { trace, kinds } = attempt(frame);
253	        expect(kinds).toEqual(["13 grab", `${frame} throw-escape`]);
254	        expect(trace[frame]!.fighters.map((fighter) => [fighter.action, fighter.health])).toEqual([
255	          ["throw-break", 1000],
256	          ["throw-break", 1000],
257	        ]);
258	      }
259	      // A press on the grab frame is too early and one on frame 24 too late.
260	      expect(attempt(13).kinds).toEqual(["13 grab", "24 throw"]);
261	      expect(attempt(24).kinds).toEqual(["13 grab", "24 throw"]);
