381	describe("frame advantage", () => {
382	  // The heavy mid reaches a standing hurtbox whose origin is less than 1280 sub-pixels (80 px) away.
383	  const blocked = (start: DuelState, punishAt?: number) => {
384	    const inputs = script(hold(1, HEAVY, R), hold(60, 0, R));
385	    if (punishAt !== undefined) for (let frame = punishAt; frame <= inputs.length; frame++) inputs[frame - 1] = [0, frame === punishAt ? LIGHT : 0];
386	    return run(start, inputs);
387	  };
388	
389	  for (const [label, start] of [
390	    ["at its longest reach, in the corner", cornered(1279)],
391	    ["midscreen, with the defender walking back", duel(5000, 5512)],
392	  ] as const) {
393	    it(`makes the heavy mid −12 on block and punishable by a jab (${label})`, () => {
394	      const trace = blocked(start);
395	      expect(events(trace).map(({ frame, kind }) => `${frame} ${kind}`)).toEqual(["19 block"]);
396	      const attackerFree = firstFreeFrame(trace, 0, 19);
397	      const defenderFree = firstFreeFrame(trace, 1, 19);
398	      expect(attackerFree - defenderFree).toBe(12);
399	      // The blocked heavy leaves at most 1343 sub-pixels; the jab reaches a standing hurtbox up to 1343 away.
400	      const [attacker, defender] = trace[19]!.fighters;
401	      expect(defender.x - attacker.x).toBeLessThanOrEqual(1343);
402	
403	      const punished = blocked(start, defenderFree);
404	      const jab = events(punished).find((event) => event.attacker === 1)!;
405	      expect(jab).toMatchObject({ kind: "hit", moveId: "jab", frame: defenderFree + 7 });
406	      expect(jab.frame).toBeLessThan(attackerFree);
